<script lang="ts">
	import { AlertBanner, PageHeader } from './ui';
	const reports=[
		{title:'Presensi',description:'Check-in, check-out, dan status presensi hingga 10.000 baris terbaru.',path:'/v1/reports/attendance.csv',file:'attendance-report.csv'},
		{title:'Payroll',description:'Rekap net amount karyawan berdasarkan periode payroll.',path:'/v1/reports/payroll.csv',file:'payroll-report.csv'},
		{title:'Cuti',description:'Riwayat pengajuan cuti, tanggal, status, dan alasan.',path:'/v1/reports/leave.csv',file:'leave-report.csv'},
		{title:'Buku besar',description:'Baris jurnal posted dengan akun debit dan kredit.',path:'/v1/reports/accounting.csv',file:'accounting-ledger.csv'}
	];
	let downloading=$state(''),error=$state('');
	async function download(path:string,file:string){downloading=path;error='';try{const response=await fetch(path,{credentials:'include'});if(!response.ok)throw new Error('Ekspor gagal disiapkan.');const url=URL.createObjectURL(await response.blob());const anchor=document.createElement('a');anchor.href=url;anchor.download=file;anchor.click();URL.revokeObjectURL(url);}catch(cause){error=cause instanceof Error?cause.message:'Ekspor gagal.';}finally{downloading='';}}
</script>
<main class="workspace-page reports-page"><PageHeader title="Reports" description="Ekspor data native server-side; laporan tidak perlu dimuat penuh ke browser." backHref="/admin/dashboard"/>{#if error}<AlertBanner title="Ekspor belum tersedia" message={error}/>{/if}<section class="panel"><div class="intro"><h2>Pusat ekspor</h2><p>CSV dapat dibuka di Excel, Google Sheets, atau perangkat akuntansi. PDF dan laporan terjadwal masih berada pada batch berikutnya.</p></div><div class="report-grid">{#each reports as report}<article><div><h3>{report.title}</h3><p>{report.description}</p></div><button class="quiet" disabled={Boolean(downloading)} onclick={()=>void download(report.path,report.file)}>{downloading===report.path?'Menyiapkan…':'Unduh CSV'}</button></article>{/each}</div></section></main>
<style>.reports-page{display:grid;gap:12px}.panel{padding:14px;border-radius:var(--radius)}h2,h3{margin:0;color:var(--ink)}h2{font-size:14px}h3{font-size:13px}.intro p,article p{color:var(--muted);font-size:12px;line-height:1.5}.report-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px}article{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;border:1px solid var(--line);border-radius:var(--radius-sm);background:var(--surface-alt)}article p{margin:4px 0 0}@media(max-width:680px){.report-grid{grid-template-columns:1fr}article{align-items:flex-start;flex-direction:column}}</style>
